source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdint>

#define THREADS 256

__global__ void compute_partial_stats_kernel(const float* __restrict__ x, float* __restrict__ sum, float* __restrict__ sumsq,
                                              int N, int C, int H, int W) {
    int c = blockIdx.x;
    int HW = H * W;
    long count = (long)N * HW;
    long chunk = (count + gridDim.y - 1) / gridDim.y;
    long start = (long)blockIdx.y * chunk;
    long end = start + chunk;
    if (end > count) end = count;
    float s = 0.0f;
    float sq = 0.0f;
    for (long idx = start + threadIdx.x; idx < end; idx += blockDim.x) {
        long n = idx / HW;
        long hw = idx % HW;
        long offset = (n * (long)C + c) * (long)HW + hw;
        float val = x[offset];
        s += val;
        sq += val * val;
    }
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        s += __shfl_down_sync(mask, s, off);
        sq += __shfl_down_sync(mask, sq, off);
    }
    __shared__ float warp_sum[THREADS / 32];
    __shared__ float warp_sumsq[THREADS / 32];
    int warp_id = threadIdx.x >> 5;
    int lane = threadIdx.x & 31;
    if (lane == 0) {
        warp_sum[warp_id] = s;
        warp_sumsq[warp_id] = sq;
    }
    __syncthreads();
    if (warp_id == 0) {
        int num_warps = blockDim.x >> 5;
        float ss = (lane < num_warps) ? warp_sum[lane] : 0.0f;
        float sqsq = (lane < num_warps) ? warp_sumsq[lane] : 0.0f;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            ss += __shfl_down_sync(mask, ss, off);
            sqsq += __shfl_down_sync(mask, sqsq, off);
        }
        if (lane == 0) {
            atomicAdd(&sum[c], ss);
            atomicAdd(&sumsq[c], sqsq);
        }
    }
}
__global__ void compute_partial_stats_kernel_vec4(const float4* __restrict__ x4, float* __restrict__ sum, float* __restrict__ sumsq,
                                                   int N, int C, long HW_vec) {
    int c = blockIdx.x;
    long count_vec = (long)N * HW_vec;
    long chunk = (count_vec + gridDim.y - 1) / gridDim.y;
    long start = (long)blockIdx.y * chunk;
    long end = start + chunk;
    if (end > count_vec) end = count_vec;
    float s = 0.0f;
    float sq = 0.0f;
    for (long idx = start + threadIdx.x; idx < end; idx += blockDim.x) {
        long n = idx / HW_vec;
        long hw = idx % HW_vec;
        long offset = (n * (long)C + c) * HW_vec + hw;
        float4 v = __ldg(&x4[offset]);
        s += v.x + v.y + v.z + v.w;
        sq += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        s += __shfl_down_sync(mask, s, off);
        sq += __shfl_down_sync(mask, sq, off);
    }
    __shared__ float warp_sum[THREADS / 32];
    __shared__ float warp_sumsq[THREADS / 32];
    int warp_id = threadIdx.x >> 5;
    int lane = threadIdx.x & 31;
    if (lane == 0) {
        warp_sum[warp_id] = s;
        warp_sumsq[warp_id] = sq;
    }
    __syncthreads();
    if (warp_id == 0) {
        int num_warps = blockDim.x >> 5;
        float ss = (lane < num_warps) ? warp_sum[lane] : 0.0f;
        float sqsq = (lane < num_warps) ? warp_sumsq[lane] : 0.0f;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            ss += __shfl_down_sync(mask, ss, off);
            sqsq += __shfl_down_sync(mask, sqsq, off);
        }
        if (lane == 0) {
            atomicAdd(&sum[c], ss);
            atomicAdd(&sumsq[c], sqsq);
        }
    }
}
__global__ void finalize_stats_kernel(const float* __restrict__ sum, const float* __restrict__ sumsq,
                                       float* __restrict__ mean, float* __restrict__ var,
                                       long count, int C) {
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c < C) {
        float s = sum[c];
        float sq = sumsq[c];
        float m = s / (float)count;
        float v = sq / (float)count - m * m;
        mean[c] = m;
        var[c] = v;
    }
}

__global__ void bn_forward_kernel(const float* __restrict__ x, float* __restrict__ y,
                                   const float* __restrict__ scale, const float* __restrict__ shift,
                                   int N, int C, int H, int W) {
    long total = (long)N * C * H * W;
    long HW = (long)H * W;
    for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total; idx += (long)blockDim.x * gridDim.x) {
        int c = (int)((idx / HW) % C);
        y[idx] = x[idx] * scale[c] + shift[c];
    }
}
__global__ void bn_forward_kernel_vec4(const float4* __restrict__ x4, float4* __restrict__ y4,
                                        const float* __restrict__ scale, const float* __restrict__ shift,
                                        long total_vec, long HW_vec, int C) {
    for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total_vec; idx += (long)blockDim.x * gridDim.x) {
        int c = (int)((idx / HW_vec) % C);
        float s = __ldg(&scale[c]);
        float sh = __ldg(&shift[c]);
        float4 xv = __ldg(&x4[idx]);
        float4 yv;
        yv.x = xv.x * s + sh;
        yv.y = xv.y * s + sh;
        yv.z = xv.z * s + sh;
        yv.w = xv.w * s + sh;
        y4[idx] = yv;
    }
}
torch::Tensor batch_norm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
                                  torch::Tensor running_mean, torch::Tensor running_var,
                                  bool training, double momentum, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    x = x.contiguous();
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    auto y = torch::empty_like(x);
    long HW_total = (long)H * W;
    long total = (long)N * C * HW_total;
    torch::Tensor mean, var;
    if (training) {
        mean = torch::empty({C}, x.options());
        var = torch::empty({C}, x.options());
        auto sum = torch::zeros({C}, x.options());
        auto sumsq = torch::zeros({C}, x.options());
        int threads = THREADS;
        long count = (long)N * HW_total;
        long threads_l = (long)threads;
        long max_blocks_per_channel = (count + threads_l - 1) / threads_l;
        int blocksPerChannel = (int)(max_blocks_per_channel < 32 ? max_blocks_per_channel : 32);
        if (blocksPerChannel < 1) blocksPerChannel = 1;
        dim3 grid(C, blocksPerChannel);
        bool vec_ok = (HW_total % 4 == 0) &&
                      (reinterpret_cast<uintptr_t>(x.data_ptr<float>()) % 16 == 0);
        if (vec_ok) {
            long HW_vec = HW_total / 4;
            compute_partial_stats_kernel_vec4<<<grid, threads>>>(
                reinterpret_cast<const float4*>(x.data_ptr<float>()),
                sum.data_ptr<float>(), sumsq.data_ptr<float>(),
                N, C, HW_vec
            );
        } else {
            compute_partial_stats_kernel<<<grid, threads>>>(
                x.data_ptr<float>(), sum.data_ptr<float>(), sumsq.data_ptr<float>(),
                N, C, H, W
            );
        }
        int fin_threads = 256;
        int fin_blocks = (C + fin_threads - 1) / fin_threads;
        finalize_stats_kernel<<<fin_blocks, fin_threads>>>(
            sum.data_ptr<float>(), sumsq.data_ptr<float>(),
            mean.data_ptr<float>(), var.data_ptr<float>(),
            count, C
        );
        auto unbiased_var = var * ((float)count / (float)(count - 1));
        running_mean.mul_(1.0 - momentum).add_(mean * momentum);
        running_var.mul_(1.0 - momentum).add_(unbiased_var * momentum);
    } else {
        mean = running_mean;
        var = running_var;
    }
    auto inv_std = torch::rsqrt(var + eps);
    auto scale = (weight * inv_std).contiguous();
    auto shift = (bias - mean * scale).contiguous();
    int threads2 = THREADS;
    bool vec_ok2 = (HW_total % 4 == 0) &&
                   (reinterpret_cast<uintptr_t>(x.data_ptr<float>()) % 16 == 0);
    if (vec_ok2) {
        long HW_vec = HW_total / 4;
        long total_vec = total / 4;
        long blocks2_l = (total_vec + threads2 - 1) / threads2;
        int blocks2 = (int)(blocks2_l > 65535 ? 65535 : blocks2_l);
        bn_forward_kernel_vec4<<<blocks2, threads2>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            scale.data_ptr<float>(), shift.data_ptr<float>(),
            total_vec, HW_vec, C
        );
    } else {
        long blocks2_l = (total + threads2 - 1) / threads2;
        int blocks2 = (int)(blocks2_l > 65535 ? 65535 : blocks2_l);
        bn_forward_kernel<<<blocks2, threads2>>>(
            x.data_ptr<float>(), y.data_ptr<float>(),
            scale.data_ptr<float>(), shift.data_ptr<float>(),
            N, C, H, W
        );
    }
    return y;
}
